1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Customer {
23	  yearsWithMHPCO: number;
24	}
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type QuoteResult = { premium: number };
32	export type ClaimResult = { payout: number; remainingCap: number };
33	export type Result = QuoteResult | ClaimResult;
34	
35	export interface ScenarioOutcome {
36	  results: Result[];
37	}
38	
39	/**
40	 * Decimal places kept before rounding up. Enough to preserve any genuine fraction of a G,
41	 * few enough to discard the trailing noise of binary floating-point arithmetic — without
42	 * this, a premium computed as 88.00000000000001 would round up to 89.
43	 */
44	const SIGNIFICANT_DECIMAL_PLACES = 6;
45	
46	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
47	const roundUpToWholeG = (amount: number): number =>
48	  Math.ceil(Number(amount.toFixed(SIGNIFICANT_DECIMAL_PLACES)));
49	
50	const BASE_PREMIUM: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUE: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  staff: 800,
63	  potion: 400,
64	  rune: 250,
65	  moonstone: 250,
66	};
67	
68	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
69	const POLICY_FEE = 5;
70	
71	const COMPONENT_TYPES = ["rune", "moonstone"];
72	const BUILDING_BLOCK_SIZE = 3;
73	const BUILDING_BLOCK_BASE_PREMIUM = 60;
74	
75	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
76	
77	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
78	
79	const countOfType = (items: Item[], type: string): number =>
80	  items.filter((item) => item.type === type).length;
81	
82	/**
83	 * Components of one kind are bundled into building blocks of 3, each charged at
84	 * the special block rate; leftovers are charged individually.
85	 */
86	const componentGroupBasePremium = (type: string, count: number): number => {
87	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
88	  const singles = count % BUILDING_BLOCK_SIZE;
89	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
90	};
91	
92	const CURSED_SURCHARGE_RATE = 0.5;
93	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
94	/**
95	 * The quote-side threshold. Independent of HIGH_ENCHANTMENT_CLAIM_LEVEL: an item at
96	 * enchantment 7 carries the surcharge here but is still reimbursed in full on a claim.
97	 */
98	const HIGH_ENCHANTMENT_QUOTE_LEVEL = 5;
99	
100	/**
101	 * A premium modifier as a multiplicative factor: a positive rate loads the premium,
102	 * a negative rate discounts it, and a modifier that does not apply leaves it untouched.
103	 */
104	const rateFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
105	
106	const isCursed = (item: Item): boolean => item.cursed === true;
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_QUOTE_LEVEL;
109	
110	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
111	const riskMultiplierOf = (item: Item): number =>
112	  rateFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
113	  rateFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
114	
115	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
116	const mainItemsPremium = (items: Item[]): number =>
117	  sum(
118	    items
119	      .filter((item) => !isComponent(item))
120	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
121	  );
122	
123	/**
124	 * Components are priced per kind, so alike ones can bundle into building blocks.
125	 * Pricing by count means individual risk flags are not visible here — no test covers
126	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
127	 */
128	const componentsPremium = (items: Item[]): number =>
129	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
130	
131	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
132	const riskLoadedPremiumOf = (items: Item[]): number =>
133	  mainItemsPremium(items) + componentsPremium(items);
134	
135	const LOYALTY_DISCOUNT_RATE = -0.2;
136	/** Loyalty begins at the start of the second year: 1 year does not qualify, 2 do. */
137	const LOYALTY_THRESHOLD_YEARS = 2;
138	
139	const isLoyal = (customer: Customer): boolean =>
140	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
141	
142	const CONTRACT_DISCOUNT_RATE = -0.15;
143	
144	/**
145	 * Customer-level modifiers apply to the whole quote and compound. A customer's very
146	 * first insurance carries the assessment surcharge; every contract after it is
147	 * discounted instead. `previousQuotes` counts quotes already given to this customer.
148	 */
149	const customerMultiplierOf = (customer: Customer, previousQuotes: number): number => {
150	  const isFirstInsurance = previousQuotes === 0;
151	  return (
152	    rateFactor(isLoyal(customer), LOYALTY_DISCOUNT_RATE) *
153	    rateFactor(isFirstInsurance, FIRST_INSURANCE_SURCHARGE_RATE) *
154	    rateFactor(!isFirstInsurance, CONTRACT_DISCOUNT_RATE)
155	  );
156	};
157	
158	const quote = (items: Item[], customer: Customer, previousQuotes: number): QuoteResult => {
159	  const premiumBeforeFee =
160	    riskLoadedPremiumOf(items) * customerMultiplierOf(customer, previousQuotes);
161	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
162	};
163	
164	/**
165	 * Steps are not independent: each one is answered in the light of the steps before it,
166	 * so the scenario is walked as a fold that threads what has happened so far.
167	 */
168	interface Policy {
169	  items: Item[];
170	  remainingCap: number;
171	}
172	
173	interface ScenarioState {
174	  quotesSoFar: number;
175	  /** Policies issued so far, keyed by the step index of the quote that created each. */
176	  policies: Record<number, Policy>;
177	}
178	
179	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, policies: {} };
180	
181	const DEDUCTIBLE = 100;
182	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
183	
184	const insuranceSumOf = (items: Item[]): number =>
185	  sum(items.map((item) => INSURANCE_VALUE[item.type]));
186	
187	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
188	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
189	const FULL_REIMBURSEMENT_RATE = 1;
190	
191	const DRAGON_MATERIAL = "dragon";
192	
193	const isDragonMade = (item: Item): boolean => item.material === DRAGON_MATERIAL;
194	
195	/**
196	 * The claim-side threshold, named separately from isHighlyEnchanted so the two
197	 * thresholds can move independently: an item at enchantment 7 carries the quote
198	 * surcharge but is still reimbursed in full here.
199	 */
200	const isHeavilyEnchanted = (item: Item): boolean =>
201	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
202	
203	/**
204	 * Heavily enchanted items are only half covered — but dragon-made ones are reimbursed
205	 * in full regardless, the MHPCO holding dragon craftsmanship beyond reproach.
206	 */
207	const reimbursementRateOf = (item: Item): number =>
208	  isHeavilyEnchanted(item) && !isDragonMade(item)
209	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
210	    : FULL_REIMBURSEMENT_RATE;
211	
212	/**
213	 * A damage names its item by type. A damage naming a type the policy does not cover is
214	 * outside anything the specification describes, so it is reimbursed at the plain rate
215	 * rather than given a rule of its own.
216	 */
217	const reimbursementRateForDamage = (damage: Damage, items: Item[]): number => {
218	  const damagedItem = items.find((item) => item.type === damage.itemType);
219	  return damagedItem === undefined ? FULL_REIMBURSEMENT_RATE : reimbursementRateOf(damagedItem);
220	};
221	
222	/**
223	 * Each damage is reimbursed at the rate its own item earns, and the deductible is borne
224	 * by the incident as a whole — so the rates are applied first and the sum reduced once.
225	 */
226	const reimbursableDamageOf = (incident: Incident, items: Item[]): number =>
227	  sum(incident.damages.map((damage) => damage.amount * reimbursementRateForDamage(damage, items)));
228	
229	/** Draws the payout down against the policy's remaining cap, reporting what is left. */
230	const settleClaimAgainstCap = (incident: Incident, policy: Policy): ClaimResult => {
231	  const amountOwedBeforeCap = Math.max(
232	    0,
233	    reimbursableDamageOf(incident, policy.items) - DEDUCTIBLE,
234	  );
235	  const payout = Math.min(amountOwedBeforeCap, policy.remainingCap);
236	  return { payout, remainingCap: policy.remainingCap - payout };
237	};
238	
239	/** Records a policy under its step index, leaving the rest of the scenario state untouched. */
240	const withPolicy = (state: ScenarioState, policyKey: number, policy: Policy): ScenarioState => ({
241	  ...state,
242	  policies: { ...state.policies, [policyKey]: policy },
243	});
244	
245	/**
246	 * Claims name their policy by the step index of the quote that issued it. The
247	 * specification describes no claim against a policy that was never issued, so rather
248	 * than inventing a payout for that case this reports the bad reference plainly —
249	 * the index signature on `policies` would otherwise let it through as an undefined
250	 * policy and fail further downstream, where the cause is no longer visible.
251	 */
252	const policyIssuedAt = (state: ScenarioState, policyKey: number): Policy => {
253	  const policy: Policy | undefined = state.policies[policyKey];
254	  if (policy === undefined) {
255	    throw new Error(`Claim references policy ${policyKey}, which was never issued`);
256	  }
257	  return policy;
258	};
259	
260	const applyStep = (
261	  state: ScenarioState,
262	  step: Step,
263	  customer: Customer,
264	  stepIndex: number,
265	): { state: ScenarioState; result: Result } => {
266	  if (step.op === "quote") {
267	    const policy: Policy = {
268	      items: step.items,
269	      remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items),
270	    };
271	    return {
272	      state: withPolicy({ ...state, quotesSoFar: state.quotesSoFar + 1 }, stepIndex, policy),
273	      result: quote(step.items, customer, state.quotesSoFar),
274	    };
275	  }
276	  const policy = policyIssuedAt(state, step.policy);
277	  const result = settleClaimAgainstCap(step.incident, policy);
278	  return {
279	    state: withPolicy(state, step.policy, { ...policy, remainingCap: result.remainingCap }),
280	    result,
281	  };
282	};
283	
284	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
285	  const results: Result[] = [];
286	  let state = INITIAL_STATE;
287	  for (const [stepIndex, step] of scenario.steps.entries()) {
288	    const stepOutcome = applyStep(state, step, scenario.customer, stepIndex);
289	    state = stepOutcome.state;
290	    results.push(stepOutcome.result);
291	  }
292	  return { results };
293	};
