2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	/** The stdin file descriptor: reading it whole is how the scenario arrives. */
5	const STDIN_FILE_DESCRIPTOR = 0;
6	
7	const scenario = JSON.parse(readFileSync(STDIN_FILE_DESCRIPTOR, "utf8")) as Scenario;
8	process.stdout.write(JSON.stringify(runScenario(scenario)));
