type StepOutcome = { state: ScenarioState; result: Result };

/** A quote issues a policy capped at a multiple of the insurance sum, and counts towards the customer's contract history. */
const applyQuote = (
  state: ScenarioState,
  items: Item[],
  customer: Customer,
  policyKey: number,
): StepOutcome => {
  const policy: Policy = {
    items,
    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
  };
  return {
    state: withPolicy({ ...state, quotesSoFar: state.quotesSoFar + 1 }, policyKey, policy),
    result: quote(items, customer, state.quotesSoFar),
  };
};

/** A claim draws down the named policy's cap, leaving the reduced policy in the state. */
const applyClaim = (
  state: ScenarioState,
  incident: Incident,
  policyKey: number,
): StepOutcome => {
  const policy = policyIssuedAt(state, policyKey);
  const result = settleClaimAgainstCap(incident, policy);
  return {
    state: withPolicy(state, policyKey, { ...policy, remainingCap: result.remainingCap }),
    result,
  };
};

const applyStep = (
  state: ScenarioState,
  step: Step,
  customer: Customer,
  stepIndex: number,
): StepOutcome =>
  step.op === "quote"
    ? applyQuote(state, step.items, customer, stepIndex)
    : applyClaim(state, step.incident, step.policy);

